// `on:click`/`on:keydown`/`on:pointerdown` and not `onClick` etc.: Solid
// delegates those to the document, so `stopPropagation()` can no longer stop
// the listeners the page hangs there directly.
import { For, createMemo, createSignal } from 'solid-js';
import type { JSX } from 'solid-js';
import { text } from '../../stores/view.js';
import './edit.css';

export type IconState = {
  on: boolean;
  title?: string;
  action?: (e?: Event) => void;
  opPointerDown?: (e: PointerEvent) => void;
};

export type ActionStripProps = {
  voor?: JSX.Element;
  drag?: IconState;
  edit?: IconState;
  duplicate?: IconState;
  remove?: IconState;
  label?: string;
  ref?: (el: HTMLElement) => void;
};

type IconKey = 'drag' | 'edit' | 'duplicate' | 'remove';

const ORDER: { key: IconKey; glyph: string; cls: string; pointer: boolean }[] = [
  { key: 'drag', glyph: '⠿', cls: 'strook-sleep', pointer: true },
  { key: 'edit', glyph: '✎', cls: 'strook-bewerk', pointer: false },
  { key: 'duplicate', glyph: '⧉', cls: 'strook-dup', pointer: false },
  { key: 'remove', glyph: '✕', cls: 'strook-weg', pointer: false },
];

export function SlotIcon(): JSX.Element {
  return (
    <span class="edit-slotje" aria-hidden="true">
      <svg
        viewBox="0 0 12 14" width="9" height="11"
        ref={(n: SVGSVGElement) => n.setAttribute('focusable', 'false')}
      >
        <path
          d="M3.3 6.2V4.3a2.7 2.7 0 0 1 5.4 0v1.9"
          fill="none" stroke="currentColor" stroke-width="1.3"
        />
        <rect x="1.6" y="6.2" width="8.8" height="6.6" rx="1.4" fill="currentColor" />
      </svg>
    </span>
  );
}

export function actionState(opts: {
  allow: boolean;
  title?: string;
  action?: (e?: Event) => void;
  unlockable?: boolean;
  onUnlock?: (e?: Event) => void;
  unlockExplanation?: string;
  notApplicable?: string;
}): IconState {
  if (opts.allow) return { on: true, title: opts.title, action: opts.action };
  if (opts.unlockable && opts.onUnlock) {
    const reason = [text('edit.notEditSource'), opts.unlockExplanation]
      .filter(Boolean).join(' ');
    return {
      on: false,
      title: opts.title ? `${opts.title} — ${reason}` : reason,
      action: opts.onUnlock,
    };
  }
  return { on: false, title: opts.notApplicable || text('edit.noEditSource') };
}

export function unlockExplanation(
  target: { name: string; current?: string; warn: boolean },
): string {
  return [
    text('edit.editSourceHint', { bron: target.name }),
    target.current ? text('edit.editSourceSwitches', { huidig: target.current }) : '',
    target.warn ? text('src.lockWarning') : '',
  ].filter(Boolean).join(' ');
}

const isActivateKey = (e: KeyboardEvent) => e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar';

function stopKey(e: Event): void {
  e.preventDefault();
  e.stopPropagation();
}

export function ActionStrip(props: ActionStripProps): JSX.Element {
  const refs = new Map<IconKey, HTMLElement>();
  const [active, setActive] = createSignal(0);

  const present = createMemo(() => ORDER
    .map((d) => ({ ...d, spec: props[d.key] }))
    .filter((d): d is typeof d & { spec: IconState } => !!d.spec));

  const row = () => present().map((d) => refs.get(d.key)).filter(Boolean) as HTMLElement[];
  const moveTo = (i: number) => {
    const n = present().length;
    if (!n) return;
    const target = ((i % n) + n) % n;
    setActive(target);
    row()[target]?.focus();
  };

  return (
    <span
      ref={(el: HTMLElement) => props.ref?.(el)}
      class="actie-strook"
      role="toolbar"
      aria-label={props.label || text('edit.stripLabel')}
      on:keydown={(e: KeyboardEvent) => {
        if (e.key === 'ArrowRight') { stopKey(e); moveTo(active() + 1); }
        else if (e.key === 'ArrowLeft') { stopKey(e); moveTo(active() - 1); }
        else if (e.key === 'Home') { stopKey(e); moveTo(0); }
        else if (e.key === 'End') { stopKey(e); moveTo(present().length - 1); }
      }}
    >
      {props.voor}
      <For each={present()}>{(d, index) => {
        const dragFn = () => (d.spec.on && d.pointer && d.spec.opPointerDown
          ? d.spec.opPointerDown : null);
        const hasAction = () => !!dragFn() || typeof d.spec.action === 'function';
        const cls = () => ['strook-knop', d.cls,
          d.spec.on ? '' : (hasAction() ? 'gelockt' : 'actie-uit'),
          dragFn() ? 'drag-handle' : ''].filter(Boolean).join(' ');
        const silent = () => !d.spec.on && !hasAction();
        return (
          <span
            ref={(el: HTMLElement) => refs.set(d.key, el)}
            class={cls()}
            role="button"
            tabindex={index() === active() ? '0' : '-1'}
            title={d.spec.title}
            aria-label={d.spec.title && dragFn()
              ? `${d.spec.title} — ${text('edit.dragHandleKey')}` : d.spec.title}
            aria-disabled={silent() ? 'true' : undefined}
            on:focus={() => setActive(index())}
            on:pointerdown={(e: PointerEvent) => {
              const fn = dragFn();
              if (!fn) return;
              e.stopPropagation();
              fn(e);
            }}
            on:click={(e: MouseEvent) => {
              if (silent() || dragFn() || !d.spec.action) return;
              e.preventDefault();
              e.stopPropagation();
              d.spec.action(e);
            }}
            on:keydown={(e: KeyboardEvent) => {
              if (silent() || dragFn() || !d.spec.action) return;
              if (!isActivateKey(e)) return;
              stopKey(e);
              d.spec.action(e);
            }}
          >
            {d.glyph}
            {!d.spec.on && hasAction() ? <SlotIcon /> : null}
          </span>
        );
      }}</For>
    </span>
  );
}
