import * as N3 from 'n3';
import { PREFIXES } from './parse.js';
import { termOf as asTerm } from './term.js';

const { namedNode } = N3.DataFactory;

const DCT = PREFIXES.dct;
const RDFS = PREFIXES.rdfs;
const XSD = PREFIXES.xsd;

export const TITLE_PREDS = [DCT + 'title', RDFS + 'label'];
export const NOTE_PREDS = [DCT + 'description', RDFS + 'comment'];
export const DATE_DEFAULT = { datatype: XSD + 'date' };

export { termOf } from './term.js';

export function bearingPred(store, termOrIri, preds) {
  if (!store || !termOrIri) return preds[0];
  const t = asTerm(termOrIri);
  if (!t) return preds[0];
  for (const p of preds) {
    if (store.getQuads(t, namedNode(p), null, null).length) return p;
  }
  return preds[0];
}

export { shownLiteral, literalShape, setDisplayedLiteral } from './edit.js';

export { validIriText } from './edit.js';

export function matchesPattern(value, pattern) {
  if (!pattern || value === '') return true;
  try { return new RegExp(pattern).test(value); } catch { return true; }
}
